def _active_managers(hass: HomeAssistant) -> list[ReminderManager]:
    """Persons that are loaded or currently being set up (not unloading)."""
    return [
        entry.runtime_data
        for entry in hass.config_entries.async_entries(DOMAIN)
        if entry.state in (ConfigEntryState.LOADED, ConfigEntryState.SETUP_IN_PROGRESS)
        and isinstance(getattr(entry, "runtime_data", None), ReminderManager)
    ]


def _language(hass: HomeAssistant) -> str:
    language = (hass.config.language or "en").split("-")[0]
    return language if language in TEXTS else "en"


def _texts(hass: HomeAssistant) -> dict[str, str]:
    return TEXTS[_language(hass)]


def _view_paths(managers: list[ReminderManager]) -> dict[str, str]:
    """Unique view path per person."""
    paths: dict[str, str] = {}
    for manager in sorted(managers, key=lambda m: m.person.lower()):
        path = slugify(manager.person) or manager.entry_id.lower()
        if path in paths.values():
            path = f"{path}-{manager.entry_id[-6:].lower()}"
        paths[manager.entry_id] = path
    return paths


def body_url(hass: HomeAssistant, entry_id: str) -> str:
    """URL of a person's body view (opened from the measurement reminder)."""
    path = _view_paths(_active_managers(hass)).get(entry_id)
    if path is None:
        return f"/{DASHBOARD_URL}"
    return f"/{DASHBOARD_URL}/{path}-{_texts(hass)['body_path']}"


def _press(entity_id: str, confirmation: str | None = None) -> dict[str, Any]:
    action: dict[str, Any] = {
        "action": "perform-action",
        "perform_action": "button.press",
        "target": {"entity_id": entity_id},
    }
    if confirmation:
        action["confirmation"] = {"text": confirmation}
    return action


def _state_is(entity_id: str, state: str) -> list[dict[str, Any]]:
    return [{"condition": "state", "entity": entity_id, "state": state}]


def _gauge(entity_id: str, name: str) -> dict[str, Any]:
    return {
        "type": "gauge",
        "entity": entity_id,
        "name": name,
        "min": 0,
        "max": 100,
        "needle": True,
        "severity": {"green": 90, "yellow": 70, "red": 0},
        "grid_options": {"columns": 6},
        # A gauge shows an error card while the value is unknown (no dose
        # taken or missed yet), so only show it once there is a number.
        "visibility": [{"condition": "numeric_state", "entity": entity_id, "above": -1}],
    }


def _no_data(entity_id: str, text: str) -> dict[str, Any]:
    """Placeholder shown instead of the gauges while there is no data yet."""
    return {
        "type": "markdown",
        "content": text,
        "visibility": [
            {"condition": "state", "entity": entity_id, "state": ["unknown", "unavailable"]}
        ],
    }


class _Ids:
    """Look up entity ids by unique id (robust against renames and language)."""

    def __init__(self, hass: HomeAssistant) -> None:
        self._registry = er.async_get(hass)

    def get(self, domain: str, unique_id: str) -> str | None:
        return self._registry.async_get_entity_id(domain, DOMAIN, unique_id)


def _medication_cards(
    ids: _Ids, manager: ReminderManager, texts: dict[str, str]
) -> tuple[list[dict], list[dict], list[dict], list[str], list[str]]:
    """Cards per medication: (take now, today, per-medication entities, charts, logbook)."""
    now_cards: list[dict] = []
    today_cards: list[dict] = []
    stats_rows: list[dict] = []
    chart_ids: list[str] = []
    status_ids: list[str] = []

    for med in sorted(manager.medications.values(), key=lambda m: m.name.lower()):
        uid = med.id
        due = ids.get("binary_sensor", f"{uid}_due")
        taken = ids.get("button", f"{uid}_taken")
        snooze = ids.get("button", f"{uid}_snooze")
        skip = ids.get("button", f"{uid}_skip")
        status = ids.get("sensor", f"{uid}_status")
        next_dose = ids.get("sensor", f"{uid}_next_dose")
        last_taken = ids.get("sensor", f"{uid}_last_taken")
        adherence_7 = ids.get("sensor", f"{uid}_adherence_7d")
        adherence_30 = ids.get("sensor", f"{uid}_adherence_30d")
        streak = ids.get("sensor", f"{uid}_streak")
        reminders = ids.get("switch", f"{uid}_reminders")
        title = f"{med.name} {med.dosage}".strip()

        if due and taken:
            now_cards.append(
                {
                    "type": "tile",
                    "entity": taken,
                    "name": f"{title} {texts['taken']}",
                    "icon": "mdi:check-circle",
                    "color": "green",
                    "hide_state": True,
                    "tap_action": _press(taken),
                    "grid_options": {"columns": 8},
                    "visibility": _state_is(due, "on"),
                }
            )
        if due and snooze:
            now_cards.append(
                {
                    "type": "tile",
                    "entity": snooze,
                    "name": texts["later"],
                    "icon": "mdi:alarm-snooze",
                    "color": "amber",
                    "hide_state": True,
                    "tap_action": _press(snooze),
                    "grid_options": {"columns": 4},
                    "visibility": _state_is(due, "on"),
                }
            )

        if status:
            today_cards.append(
                {
                    "type": "tile",
                    "entity": status,
                    "name": title,
                    "icon": "mdi:pill",
                    "grid_options": {"columns": 6},
                }
            )
            status_ids.append(status)
        if next_dose:
            today_cards.append(
                {
                    "type": "tile",
                    "entity": next_dose,
                    "name": texts["next"],
                    "grid_options": {"columns": 6},
                }
            )
        if taken:
            today_cards.append(
                {
                    "type": "tile",
                    "entity": taken,
                    "name": texts["taken"].capitalize(),
                    "color": "green",
                    "hide_state": True,
                    "tap_action": _press(taken, texts["confirm_taken"].format(name=med.name)),
                    "grid_options": {"columns": 4},
                }
            )
        if skip:
            today_cards.append(
                {
                    "type": "tile",
                    "entity": skip,
                    "name": texts["skip"],
                    "color": "grey",
                    "hide_state": True,
                    "tap_action": _press(skip, texts["confirm_skip"].format(name=med.name)),
                    "grid_options": {"columns": 4},
                }
            )
        if reminders:
            today_cards.append(
                {
                    "type": "tile",
                    "entity": reminders,
                    "name": texts["remind"],
                    "grid_options": {"columns": 4},
                }
            )

        for entity_id, label in (
            (adherence_7, texts["days_7"]),
            (adherence_30, texts["days_30"]),
            (streak, None),  # entity name is already "<medication> Serie"
            (last_taken, None),
        ):
            if entity_id:
                row: dict[str, Any] = {"entity": entity_id}
                if label:
                    row["name"] = f"{med.name} · {label}"
                stats_rows.append(row)
        if adherence_7:
            chart_ids.append(adherence_7)

    return now_cards, today_cards, stats_rows, chart_ids, status_ids


def _manage_cards(ids: _Ids, manager: ReminderManager, texts: dict[str, str]) -> list[dict]:
    """Cards to edit, add and delete medications."""
    cards: list[dict[str, Any]] = [
        {"type": "heading", "heading": texts["manage"], "icon": "mdi:cog"},
        {"type": "markdown", "content": texts["manage_hint"]},
    ]
    for med in sorted(manager.medications.values(), key=lambda m: m.name.lower()):
        rows: list[Any] = [
            entity_id
            for entity_id in (
                ids.get("text", f"{med.id}_cfg_name"),
                ids.get("text", f"{med.id}_cfg_times"),
                ids.get("text", f"{med.id}_cfg_weekdays"),
                ids.get("text", f"{med.id}_cfg_dosage"),
                ids.get("number", f"{med.id}_cfg_early_minutes"),
                ids.get("number", f"{med.id}_cfg_late_minutes"),
                ids.get("switch", f"{med.id}_reminders"),
            )
            if entity_id
        ]
        if delete := ids.get("button", f"{med.id}_delete_medication"):
            rows.append(
                {
                    "type": "button",
                    "name": texts["delete"],
                    "icon": "mdi:delete",
                    "action_name": texts["delete"],
                    "tap_action": _press(delete, texts["confirm_delete"].format(name=med.name)),
                }
            )
        cards.append(
            {
                "type": "entities",
                "title": med.name,
                "state_color": True,
                "entities": rows,
                "grid_options": {"columns": 6},
            }
        )

    eid = manager.entry_id
    new_rows: list[Any] = [
        entity_id
        for entity_id in (
            ids.get("text", f"{eid}_new_name"),
            ids.get("text", f"{eid}_new_times"),
            ids.get("text", f"{eid}_new_dosage"),
        )
        if entity_id
    ]
    if add := ids.get("button", f"{eid}_add_medication"):
        new_rows.append(
            {
                "type": "button",
                "name": texts["new_medication"],
                "icon": "mdi:plus-circle",
                "action_name": texts["add"],
                "tap_action": _press(add, texts["confirm_add"]),
            }
        )
    cards.append(
        {
            "type": "entities",
            "title": texts["new_medication"],
            "entities": new_rows,
            "grid_options": {"columns": 6},
        }
    )
    return cards


def _person_view(
    hass: HomeAssistant,
    ids: _Ids,
    manager: ReminderManager,
    texts: dict[str, str],
    admin_ids: list[str],
    path: str,
) -> dict[str, Any]:
    eid = manager.entry_id
    any_due = ids.get("binary_sensor", f"{eid}_any_due")
    open_today = ids.get("sensor", f"{eid}_open_today")
    taken_today = ids.get("sensor", f"{eid}_taken_today")
    missed_today = ids.get("sensor", f"{eid}_missed_today")
    skipped_today = ids.get("sensor", f"{eid}_skipped_today")
    adherence_7 = ids.get("sensor", f"{eid}_adherence_7d")
    adherence_30 = ids.get("sensor", f"{eid}_adherence_30d")
    calendar = ids.get("calendar", f"{eid}_doses")

    now_cards, today_cards, stats_rows, chart_ids, status_ids = _medication_cards(
        ids, manager, texts
    )
    sections: list[dict[str, Any]] = []

    # 1) Take now - only while something is due
    if any_due and now_cards:
        sections.append(
            {
                "type": "grid",
                "visibility": _state_is(any_due, "on"),
                "cards": [
                    {"type": "heading", "heading": texts["now"], "icon": "mdi:bell-ring"},
                    *now_cards,
                ],
            }
        )

    # 2) Today
    today: list[dict[str, Any]] = [
        {"type": "heading", "heading": texts["today"], "icon": "mdi:calendar-today"}
    ]
    if not manager.medications:
        today.append({"type": "markdown", "content": texts["no_medication"]})
    elif any_due:
        today.append(
            {
                "type": "markdown",
                "content": texts["nothing_due"],
                "visibility": _state_is(any_due, "off"),
            }
        )
    today.extend(today_cards)
    sections.append({"type": "grid", "cards": today})

    # 3) Summary
    summary: list[dict[str, Any]] = [
        {"type": "heading", "heading": texts["balance"], "icon": "mdi:chart-arc"}
    ]
    for entity_id, color in (
        (taken_today, "green"),
        (missed_today, "red"),
        (skipped_today, "grey"),
    ):
        if entity_id:
            summary.append(
                {
                    "type": "tile",
                    "entity": entity_id,
                    "color": color,
                    "grid_options": {"columns": 4},
                }
            )
    if adherence_7:
        summary.append(_no_data(adherence_7, texts["no_data"]))
        summary.append(_gauge(adherence_7, texts["days_7"]))
    if adherence_30:
        summary.append(_gauge(adherence_30, texts["days_30"]))
    if stats_rows:
        summary.append(
            {"type": "entities", "title": texts["per_medication"], "entities": stats_rows}
        )
    sections.append({"type": "grid", "cards": summary})

    # 4) History
    history: list[dict[str, Any]] = [
        {"type": "heading", "heading": texts["history"], "icon": "mdi:chart-line"}
    ]
    chart_entities = ([{"entity": adherence_7, "name": texts["total"]}] if adherence_7 else []) + [
        {"entity": entity_id} for entity_id in chart_ids
    ]
    if chart_entities:
        history.append(
            {
                "type": "statistics-graph",
                "title": texts["adherence_chart"],
                "chart_type": "line",
                "period": "day",
                "days_to_show": 30,
                "stat_types": ["mean"],
                "entities": chart_entities,
                "grid_options": {"columns": "full"},
                **(
                    {
                        "visibility": [
                            {"condition": "numeric_state", "entity": adherence_7, "above": -1}
                        ]
                    }
                    if adherence_7
                    else {}
                ),
            }
        )
    if status_ids:
        history.append(
            {
                "type": "history-graph",
                "title": texts["status_chart"],
                "hours_to_show": 168,
                "entities": status_ids,
                "grid_options": {"columns": "full"},
            }
        )
    if len(history) > 1:
        sections.append({"type": "grid", "column_span": 2, "cards": history})

    # 5) Calendar
    if calendar:
        sections.append(
            {
                "type": "grid",
                "column_span": 3,
                "cards": [
                    {"type": "heading", "heading": texts["calendar"], "icon": "mdi:calendar-check"},
                    {
                        "type": "calendar",
                        "initial_view": "listWeek",
                        "entities": [calendar],
                        "grid_options": {"columns": "full"},
                    },
                ],
            }
        )

    # 6) Log
    if status_ids:
        sections.append(
            {
                "type": "grid",
                "column_span": 3,
                "cards": [
                    {
                        "type": "heading",
                        "heading": texts["log"],
                        "icon": "mdi:format-list-bulleted",
                    },
                    {
                        "type": "logbook",
                        "hours_to_show": 168,
                        "target": {"entity_id": status_ids},
                        "grid_options": {"columns": "full"},
                    },
                ],
            }
        )

    view: dict[str, Any] = {
        "title": manager.person,
        "path": path,
        "icon": DASHBOARD_ICON,
        "type": "sections",
        "max_columns": 3,
        "badges": [
            {"type": "entity", "entity": entity_id, "show_name": True}
            for entity_id in (open_today, taken_today, missed_today, adherence_7)
            if entity_id
        ],
        "sections": sections,
    }
    _restrict(view, manager, admin_ids)
    return view


def _restrict(view: dict[str, Any], manager: ReminderManager, admin_ids: list[str]) -> None:
    """Only the person's own user and administrators see a view."""
    visible_users = list(dict.fromkeys([u for u in [manager.user_id, *admin_ids] if u]))
    if visible_users:
        view["visible"] = [{"user": user_id} for user_id in visible_users]


def _manage_view(
    hass: HomeAssistant,
    ids: _Ids,
    manager: ReminderManager,
    texts: dict[str, str],
    admin_ids: list[str],
    path: str,
    title: str,
) -> dict[str, Any]:
    """Separate tab to manage medications and measurement settings."""
    sections: list[dict[str, Any]] = [
        {"type": "grid", "column_span": 3, "cards": _manage_cards(ids, manager, texts)}
    ]
    if manager.body.enabled:
        sections.append(
            {
                "type": "grid",
                "column_span": 3,
                "cards": _measurement_settings_cards(hass, ids, manager.body, texts),
            }
        )
    view: dict[str, Any] = {
        "title": title,
        "path": path,
        "icon": "mdi:cog",
        "type": "sections",
        "max_columns": 3,
        "sections": sections,
    }
    _restrict(view, manager, admin_ids)
    return view


# ---------------------------------------------------------------- measurements


def _when(entity_id: str, state: str | list[str]) -> list[dict[str, Any]]:
    return [{"condition": "state", "entity": entity_id, "state": state}]


def _has_number(entity_id: str) -> list[dict[str, Any]]:
    # Gauges and graphs show an error while the value is unknown.
    return [{"condition": "numeric_state", "entity": entity_id, "above": 0}]


def _hint(entity_id: str, text: str) -> dict[str, Any]:
    """Shown instead of a gauge or graph while there is no value yet."""
    return {
        "type": "markdown",
        "content": text,
        "visibility": _when(entity_id, ["unknown", "unavailable"]),
    }


def _tile(entity_id: str, columns: int = 6, **extra: Any) -> dict[str, Any]:
    return {"type": "tile", "entity": entity_id, "grid_options": {"columns": columns}, **extra}


def _body_view(
    hass: HomeAssistant,
    ids: _Ids,
    body: BodyTracker,
    texts: dict[str, str],
    path: str,
) -> dict[str, Any]:
    """Enter today's values, last values, trend, BMI / WHtR and history."""
    eid = body.entry_id
    lang = _language(hass)
    metrics = body.tracked_keys()
    sections: list[dict[str, Any]] = []

    # 1) Enter today's values
    enter: list[dict[str, Any]] = [
        {"type": "heading", "heading": texts["enter"], "icon": "mdi:pencil-plus"}
    ]
    for key in metrics:
        if due := ids.get("binary_sensor", f"{eid}_{key}_due"):
            enter.append(
                {
                    "type": "markdown",
                    "content": texts["missing"].format(metric=metric_title(key, lang)),
                    "visibility": _when(due, "on"),
                }
            )
    inputs = [
        {"entity": entity_id, "icon": METRIC_ICONS.get(key, "mdi:pencil")}
        for key in metrics
        if (entity_id := ids.get("number", f"{eid}_{key}_input"))
    ]
    if inputs:
        enter.append({"type": "entities", "entities": inputs})
        enter.append({"type": "markdown", "content": texts["enter_hint"]})
    sections.append({"type": "grid", "cards": enter})

    # 2) One section per measurement type
    for key in metrics:
        cards: list[dict[str, Any]] = [
            {
                "type": "heading",
                "heading": metric_title(key, lang),
                "icon": METRIC_ICONS.get(key, "mdi:chart-line"),
            }
        ]
        for sensor_key, columns in (
            ("last", 6),
            ("last_measured", 6),
            ("change_7d", 4),
            ("change_30d", 4),
            ("trend_direction", 4),
        ):
            if entity_id := ids.get("sensor", f"{eid}_{key}_{sensor_key}"):
                cards.append(_tile(entity_id, columns))
        sections.append({"type": "grid", "cards": cards})

    # 3) BMI and waist-to-height ratio
    derived: list[dict[str, Any]] = [
        {"type": "heading", "heading": texts["body"], "icon": "mdi:human"}
    ]
    if WEIGHT.key in metrics and (bmi := ids.get("sensor", f"{eid}_bmi")):
        derived.append(_hint(bmi, texts["no_bmi"]))
        derived.append(
            {
                "type": "gauge",
                "entity": bmi,
                "name": texts["bmi"],
                "min": 15,
                "max": 40,
                "needle": True,
                "segments": [
                    {"from": 0, "color": "#039be5", "label": texts["underweight"]},
                    {"from": 18.5, "color": "#43a047", "label": texts["normal"]},
                    {"from": 25, "color": "#ffa600", "label": texts["overweight"]},
                    {"from": 30, "color": "#db4437", "label": texts["obese"]},
                ],
                "grid_options": {"columns": 6},
                "visibility": _has_number(bmi),
            }
        )
        if category := ids.get("sensor", f"{eid}_bmi_category"):
            derived.append(_tile(category, 6, visibility=_has_number(bmi)))
    if WAIST.key in metrics and (whtr := ids.get("sensor", f"{eid}_whtr")):
        derived.append(_hint(whtr, texts["no_whtr"]))
        derived.append(
            {
                "type": "gauge",
                "entity": whtr,
                "name": texts["whtr"],
                "min": 0.3,
                "max": 0.8,
                "needle": True,
                "segments": [
                    {"from": 0, "color": "#43a047", "label": texts["healthy"]},
                    {"from": 0.5, "color": "#ffa600", "label": texts["increased"]},
                    {"from": 0.6, "color": "#db4437", "label": texts["high"]},
                ],
                "grid_options": {"columns": 6},
                "visibility": _has_number(whtr),
            }
        )
        if category := ids.get("sensor", f"{eid}_whtr_category"):
            derived.append(_tile(category, 6, visibility=_has_number(whtr)))
    if len(derived) > 1:
        derived.append({"type": "markdown", "content": f"<small>{texts['disclaimer']}</small>"})
        sections.append({"type": "grid", "cards": derived})

    # 4) History graphs (long-term statistics: mean, min, max per day)
    history: list[dict[str, Any]] = [
        {"type": "heading", "heading": texts["body_history"], "icon": "mdi:chart-line"}
    ]
    for key in metrics:
        if last := ids.get("sensor", f"{eid}_{key}_last"):
            history.append(_hint(last, f"{metric_title(key, lang)}: {texts['no_history']}"))
            history.append(
                {
                    "type": "statistics-graph",
                    "title": metric_title(key, lang),
                    "chart_type": "line",
                    "period": "day",
                    "days_to_show": 90,
                    "stat_types": ["mean", "min", "max"],
                    "entities": [last],
                    "grid_options": {"columns": "full"},
                    "visibility": _has_number(last),
                }
            )
    if len(history) > 1:
        sections.append({"type": "grid", "column_span": 3, "cards": history})

    badges = [
        {"type": "entity", "entity": entity_id, "show_name": True}
        for entity_id in (
            *(ids.get("sensor", f"{eid}_{key}_last") for key in metrics),
            ids.get("sensor", f"{eid}_bmi") if WEIGHT.key in metrics else None,
        )
        if entity_id
    ]
    return {
        "title": texts["body_tab"],
        "path": path,
        "icon": BODY_ICON,
        "type": "sections",
        "max_columns": 3,
        "badges": badges,
        "sections": sections,
    }


def _measurement_settings_cards(
    hass: HomeAssistant, ids: _Ids, body: BodyTracker, texts: dict[str, str]
) -> list[dict[str, Any]]:
    """Height and the reminder of each measurement (Manage tab)."""
    eid = body.entry_id
    lang = _language(hass)
    cards: list[dict[str, Any]] = [
        {"type": "heading", "heading": texts["measurements"], "icon": BODY_ICON},
        {"type": "markdown", "content": texts["measurements_hint"]},
    ]
    if height := ids.get("number", f"{eid}_height"):
        cards.append(
            {
                "type": "entities",
                "title": texts["person"],
                "entities": [height],
                "grid_options": {"columns": 6},
            }
        )
    for key in body.tracked_keys():
        rows = [
            entity_id
            for entity_id in (
                ids.get("switch", f"{eid}_{key}_reminder"),
                ids.get("time", f"{eid}_{key}_reminder_time"),
                ids.get("text", f"{eid}_{key}_reminder_weekdays"),
            )
            if entity_id
        ]
        if rows:
            cards.append(
                {
                    "type": "entities",
                    "title": metric_title(key, lang),
                    "state_color": True,
                    "entities": rows,
                    "grid_options": {"columns": 6},
                }
            )
    cards.append({"type": "markdown", "content": texts["more_metrics"]})
    return cards


async def async_build_dashboard(hass: HomeAssistant) -> dict[str, Any]:
    """Build the dashboard config for all loaded persons."""
    texts = _texts(hass)
    ids = _Ids(hass)
    users = await hass.auth.async_get_users()
    admin_ids = [u.id for u in users if u.is_admin and u.is_active and not u.system_generated]

    managers = sorted(_active_managers(hass), key=lambda m: m.person.lower())
    paths = _view_paths(managers)
    views: list[dict[str, Any]] = []

    def tab_title(key: str, manager: ReminderManager) -> str:
        # With several persons the tab name says whose tab it is.
        return texts[key] if len(managers) == 1 else f"{texts[key]} ({manager.person})"

    for manager in managers:
        path = paths[manager.entry_id]
        views.append(_person_view(hass, ids, manager, texts, admin_ids, path))
        if manager.body.enabled:
            body_view = _body_view(hass, ids, manager.body, texts, f"{path}-{texts['body_path']}")
            body_view["title"] = tab_title("body_tab", manager)
            _restrict(body_view, manager, admin_ids)
            views.append(body_view)
        views.append(
            _manage_view(
                hass,
                ids,
                manager,
                texts,
                admin_ids,
                f"{path}-{texts['manage_path']}",
                tab_title("manage_tab", manager),
            )
        )

    if not views:
        views.append(
            {
                "title": texts["title"],
                "path": "start",
                "cards": [{"type": "markdown", "content": texts["no_person"]}],
            }
        )
    return {"title": texts["title"], "views": views}


class PillReminderDashboard(LovelaceConfig):
    """Read-only dashboard whose config is generated on every load."""

    def __init__(self, hass: HomeAssistant, title: str) -> None:
        """Initialize."""
        super().__init__(
            hass,
            DASHBOARD_URL,
            {
                "mode": "yaml",
                "title": title,
                "icon": DASHBOARD_ICON,
                "show_in_sidebar": True,
                "require_admin": False,
            },
        )

    @property
    def mode(self) -> str:
        """Generated dashboards cannot be edited in the UI."""
        return "yaml"

    async def async_get_info(self) -> dict[str, Any]:
        """Return the config info."""
        config = await self.async_load(False)
        return {"mode": self.mode, "views": len(config["views"])}

    async def async_load(self, force: bool) -> dict[str, Any]:
        """Generate the config."""
        return await async_build_dashboard(self.hass)

    async def async_json(self, force: bool) -> json_fragment:
        """Return the generated config as JSON."""
        return json_fragment(json_bytes(await self.async_load(force)))

    @callback
    def async_notify_changed(self) -> None:
        """Tell open browsers to reload the dashboard."""
        self._config_updated()


@callback
def async_update_dashboard(hass: HomeAssistant, *, removed_entry_id: str | None = None) -> None:
    """Register or refresh the dashboard; remove it when the last person is deleted.

    Unloading (e.g. a reload after adding a medication) only refreshes the
    dashboard, so it does not briefly disappear from the sidebar.
    """
    lovelace = hass.data.get(LOVELACE_DATA)
    if lovelace is None or "frontend" not in hass.config.components:
        _LOGGER.debug("Lovelace not loaded, no dashboard created")
        return

    existing = lovelace.dashboards.get(DASHBOARD_URL)

    if existing is not None and not isinstance(existing, PillReminderDashboard):
        _LOGGER.warning(
            "A dashboard with the URL /%s already exists; the Pill Reminder "
            "dashboard is not created",
            DASHBOARD_URL,
        )
        return

    if existing is not None:
        remaining = [
            e for e in hass.config_entries.async_entries(DOMAIN) if e.entry_id != removed_entry_id
        ]
        if not remaining:
            frontend.async_remove_panel(hass, DASHBOARD_URL, warn_if_unknown=False)
            lovelace.dashboards.pop(DASHBOARD_URL, None)
            return
        existing.async_notify_changed()
        return

    if not _active_managers(hass):
        return

    title = _texts(hass)["title"]
    lovelace.dashboards[DASHBOARD_URL] = PillReminderDashboard(hass, title)
    frontend.async_register_built_in_panel(
        hass,
        "lovelace",
        sidebar_title=title,
        sidebar_icon=DASHBOARD_ICON,
        frontend_url_path=DASHBOARD_URL,
        config={"mode": "yaml"},
        require_admin=False,
    )
